WITH RECURSIVE month_spine AS (SELECT DATE '2024-09-01' AS month_start, DATE '2024-09-30' AS month_end UNION ALL SELECT CAST(month_start + INTERVAL '1 month' AS DATE) AS month_start, CAST(month_start + INTERVAL '2 month' - INTERVAL '1 day' AS DATE) AS month_end FROM month_spine WHERE month_start < DATE '2026-08-01'), eligible_cards AS (SELECT c.member_id, m.month_start, m.month_end FROM {{ ref('cards') }} c JOIN month_spine m ON c.card_type IN ('悦享年卡', '家庭季卡') AND c.valid_from <= m.month_end AND m.month_end < c.valid_until AND (c.ended_at IS NULL OR m.month_end < c.ended_at)), eligible_members AS (SELECT member_id, month_start, MAX(month_end) AS month_end FROM eligible_cards GROUP BY member_id, month_start), monthly_orders AS (SELECT member_id, CAST(DATE_TRUNC('month', ordered_at) AS DATE) AS month_start, COUNT(*) AS valid_order_count, SUM(paid_cents - refund_cents) AS net_sales_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0 GROUP BY member_id, CAST(DATE_TRUNC('month', ordered_at) AS DATE)) SELECT e.member_id || '|' || CAST(e.month_start AS VARCHAR) AS member_month_key, e.member_id, e.month_start, e.month_end, COALESCE(o.valid_order_count, 0) AS valid_order_count, COALESCE(o.net_sales_cents, 0) AS net_sales_cents FROM eligible_members e LEFT JOIN monthly_orders o ON e.member_id = o.member_id AND e.month_start = o.month_start